const root = $input.first().json;
let content = root.choices?.[0]?.message?.content ?? root.message?.content ?? root.content;
if (typeof content !== 'string') content = JSON.stringify(content ?? {});
let parsed;
try { parsed = JSON.parse(content); }
catch (e) {
  const m = content.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Agent did not return JSON: ' + e.message);
  parsed = JSON.parse(m[0]);
}
const prior = $('Prepare LLM Payload').first().json;
return [{ json: {
  reportId: prior.reportId || prior.intake?.reportId || parsed.reportId,
  stage: prior.stage,
  result: parsed,
  evidenceEvent: {
    ts: new Date().toISOString(),
    stage: prior.stage,
    reportId: prior.reportId || parsed.reportId
  }
}}];
